-- Non-destructive live-DB seed: run with psql on an existing byteshop database.
-- Inserts 4 categories + 25 products only when missing; safe to re-run.
-- Also drops the legacy Electronics/Books/Clothing shelves (only when empty).

DELETE FROM public.product_category WHERE id IN (1, 2, 3) AND NOT EXISTS (SELECT 1 FROM public.product p WHERE p.category_id IN (1, 2, 3));


SELECT pg_catalog.setval('public.product_id_seq', (SELECT MAX(id) FROM public.product), true);
SELECT pg_catalog.setval('public.product_category_id_seq', (SELECT MAX(id) FROM public.product_category), true);
